COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_FAMIGLIA_CONVIVENZA IS 'identificativo della famiglia o convivenza in APR';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_COMUNE_RESIDENZA IS 'Identifica la residenza attuale della famiglia/collettività';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COGNOME_NATO IS 'Cognome Nato';

