COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_COMUNE_NASCITA IS 'Identificativo del comune di nascita';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_STATO_NASCITA IS 'Identificativo dello stato di nascita';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.DATA_NASCITA IS 'Data nascita';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.SESSO_NATO IS 'Sesso nato';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_CITTADINANZA IS 'Identifica lo stato della prima cittadinanza del soggetto nato';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.DATA_ISCRIZ_NASCITA IS 'Data di iscrizione in anagrafe per nascita del nato';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COGNOME_MADRE IS 'Cognome madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.NOME_MADRE IS 'Nome madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.DATA_NASCITA_MADRE IS 'Data nascita madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_STATO_CIVILE_MADRE IS 'Identificativo dello stato civile della madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_CITTADINANZA_MADRE IS 'Identifica lo stato della prima cittadinanza della madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COD_FISC_MADRE IS 'Codice fiscale della madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COGNOME_PADRE IS 'Cognome padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.NOME_PADRE IS 'Nome padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.DATA_NASCITA_PADRE IS 'Data nascita padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_STATO_CIVILE_PADRE IS 'Identificativo dello stato civile del padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_CITTADINANZA_PADRE IS 'Identifica lo stato della prima cittadinanza del padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COD_FISC_PADRE IS 'Codice fiscale del padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.CODICE_FAMIGLIA IS 'Codice identificativo della famiglia';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.CODICE_CONVIVENZA IS 'Codice identificativo della convivenza';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLAG_NATO_MORTO IS 'Nato Morto ([S]i o [N]o) - se iscrizione da Pubblico Ufficiale';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COD_IND_MADRE IS 'Codice utilizzato in APR per identificare univocamente il soggetto madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.COD_IND_PADRE IS 'Codice utilizzato in APR per identificare univocamente il soggetto padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_COMUNE_RESIDENZA_MADRE IS 'Identificativo del comune di residenza della madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_COMUNE_RESIDENZA_PADRE IS 'Identificativo del comune di residenza del padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.SESSO_PADRE IS 'Sesso madre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.SESSO_MADRE IS 'Sesso padre';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.CODICE_INDIVIDUALE IS 'Codice utilizzato in APR per identificare univocamente il soggetto nato';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_FLUSSO IS 'Identificativo del Flusso di RETTIFICA';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_CAUSALE IS 'Identificativo della causale di RETTIFICA';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLG_STATO_ELEBORAZIONE IS 'Flg inserimento su OUT_';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLG_STATO_RETTIFICA IS 'Flg inserimento su RETTIFICA';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.RETTIFICA_VAL_OLD IS 'In caso di rettifica contiene il vecchio valore del campo COMUNE o STATO';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.RETTIFICA_VAL_NEW IS 'In caso di rettifica contiene il nuovo valore del campo COMUNE o NAZIONE';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID IS 'Identificativo univico OUT_DECESSI';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.DATA_AGGIORNAMENTO IS 'Data ultimo aggiornamento record';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.DATA_INSERIMENTO IS 'Data inserimento record';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.NOME_OPERATORE IS 'Nome operatore';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLG_REPORT IS 'Campo Tecnico';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.REP_STATO IS 'Campo Tecnico';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_STATO_PRATICA IS 'Campo che indica lo stato della pratica.';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLG_PARTO_PLURIMO IS 'Flag che segnala se il PARTO è stato plurimo o meno. default a NULL fino allo splitting. se vi sono più figli viene impostato a ''S'' altrimenti a ''N''';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLG_NATO_OSP IS 'Flag che indica se dichiarati alla Direzione sanitaria di centro nascita';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.FLG_NATO_IN_MATRIMONIO IS 'Flag che indica seè nato all''interno del matrimonio';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ID_MUNICIPIO IS 'Identificativo del municipio della residenza del nato';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ANNO_ATTO IS 'Campo che indica l''anno in cui si registra l''atto.';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.PARTE_ATTO IS 'Campo che indica il numero della parte dell''atto.';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.SERIE_ATTO IS 'Campo che indica la serie dell''atto.';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.NUMERO_ATTO IS 'IL NUMERO ATTO VIENE CREATO COME PROGRESSIVO DA 1 A XXXXX PER SINGOLO ANNO E PARTE/SERIE';

COMMENT ON COLUMN STAT_USR.OUT_NASCITE.ESPONENTE IS 'Campo che indica l''esponente dell''atto';



