COMMENT ON COLUMN STAT_USR.OUT_UNIONI.ID_COMUNE_NASCITA_U1 IS 'Identificativo del comune di nascita del unendo 1';

COMMENT ON COLUMN STAT_USR.OUT_UNIONI.ID_STATO_NASCITA_U1 IS 'Identificativo dello stato di nascita del unendo 1';

