COMMENT ON COLUMN STAT_USR.OUT_UNIONI.ID_TITOLO_STUDIO_U1 IS 'Identificativo del titolo di studio del unendo 1';

COMMENT ON COLUMN STAT_USR.OUT_UNIONI.ID_POS_PROFESSIONALE_U1 IS 'Identificativo della posizione professionale del unendo 1';

COMMENT ON COLUMN STAT_USR.OUT_UNIONI.ID_COND_NON_PROFESSIONALE_U1 IS 'Identificativo della condizione non professionale del unendo 1';

