COMMENT ON TABLE STAT_USR.REPORT_ESITO IS 'Esito aggregato per singoli REPORT suddivisi per FLUSSO.
Il REPORT generato viene identificato tramite le relative tabelle di REP_. Dalla tabella di configurazione CONF_MODELLO in base al report si identifica il template da invocare su Pentaho tramite l''applet. 
Il template contiene la logica di business (query) estrattiva dalle REP_.';

