COMMENT ON TABLE STAT_USR.SCHEDULA_MODELLO IS 'La tabella traccia le schedulazioni dei singoli report ( procedure di generazione) impostate dalla maschera "Gestione ALL Report e Procedure".
Riprende solo le schedulazione dei processi di business sotto il controllo dell''utente di statistica.

 - Tutti i REPORT con cadenza ANNUALE, SEMESTRALE, MENSILE o con diversa frequenza su richiesta non sono predefiniti con ripetizioni secondo la cadenza richiesta...ma verranno tutti preventivamente schedulati ONESHOT su richiesta dell''utente di statistica.
 - Lo stesso REPORT potrebbe essere generato più volte ma schedulato una sola volta fino all''elaborazione


ATTENZIONE
 - Solo i flussi di allineamento delle tabelle di frontiera OUT_ verranno schedulati tramite schedulatore ORACLE e gestiti solo dall''amministratore del sistema. ';

COMMENT ON COLUMN STAT_USR.SCHEDULA_MODELLO.ID IS 'Campo che identifica la PK.';

COMMENT ON COLUMN STAT_USR.SCHEDULA_MODELLO.MODELLO IS 'FK che indica l''ID della procedura o del modello che si sta schedulando.';

COMMENT ON COLUMN STAT_USR.SCHEDULA_MODELLO.LISTA_PARAMETRI IS 'Campo che identifica la lista dei parametri. Uso per Logging.';

COMMENT ON COLUMN STAT_USR.SCHEDULA_MODELLO.INIZIO_ELABORAZIONE IS 'Campo che identifica la DATA di schedulazione.';

COMMENT ON COLUMN STAT_USR.SCHEDULA_MODELLO.ID_STATO IS 'Campo per uso futuro .Campo che identifica lo STATO in forma numerica. 0=DaElaborare, 1=InElaborazione, 2=Elaborato, 3=InErrore.';

COMMENT ON COLUMN STAT_USR.SCHEDULA_MODELLO.NOTE IS 'Campo Note. Inserito da GUI e mostrato nel riepilogo.';

