COMMENT ON TABLE STAT_USR.CONF_MODELLO IS 'Tabella di censimento di tutti i report e di tutte le proceduere.
La chiave viene usata in fase di schedulazione, dalla gui "Gestione Report e Procedure"e dalla procedure per l''elaborazione dei dati per i report.

In caso di REPORT si identifica uno scarico per la maschera se il campo PREFISSO_TABELLA_REPORT non è NULL.

Il campo PATH_TEMPLATE_PENTHAO per ora è NULL, ma appena verrà impostato uno storage per la reportistica provvediamo ad impostarlo /USER/<REPORT>/. 
   Es.    "/user/reportD4/"';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.ID IS 'Campo che identifica la PK.';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.NOME IS 'Campo che identifica il codice del modello. (AP10,P4, ..)';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.DESCRIZIONE IS 'Campo che contiene il nome per esteso del modello.';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.CADENZA IS 'Campo che identifica il tipo di schedulazione. Lista di possibili valori  M=Mensile, A=Annuale, S=Semestrale, R=SuRichiesta. ES:M,R';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.PREFISSO_TABELLA_REPORT IS 'Campo che identifica la query da effettuare per l''estrazione dei dati nel Template Pentaho.';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.NOME_PROCEDURA_REPORT IS 'Campo che identifica la procedura da invocare per generare il report.';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.NOME_TEMPLATE_PENTAHO IS 'Compo che identifica il nome del template Pentaho.';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.PATH_TEMPLATE_PENTAHO IS 'Campo che identifica il path del server dove storato il template Pentaho. Es. /user/reportP4_INT/ (/user/<MODELLO_REPORT>)';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.VISIBILE IS 'Campo che identifica la visibilità del report in Console Pentaho.';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.TIPO_REPORT IS 'Tipo del file file di report';

COMMENT ON COLUMN STAT_USR.CONF_MODELLO.FLG_SUBREPORT IS 'Flag che indica se il report di pentaho ha o meno dei subreport al suo interno. Y si, N no';



