ALTER TABLE STAT_USR.CONF_REPORT ADD (
  CONSTRAINT REPORT_CFG_C1
  CHECK (TIPO_REPORT IN ('MENSILE','SEMESTRALE','ANNUALE','A RICHIESTA'))
  ENABLE VALIDATE,
  CONSTRAINT REPORT_CFG_C2
  CHECK (TIPO_REPORT = 'MENSILE' AND TO_CHAR(DATA_INIZIO,'YYYYMM') = TO_CHAR(DATA_FINE,'YYYYMM'))
  ENABLE VALIDATE,
  CONSTRAINT REPORT_CFG_C3
  CHECK ( (TIPO_REPORT = 'MENSILE' AND TO_CHAR(DATA_INIZIO,'YYYYMM') = TO_CHAR(DATA_FINE,'YYYYMM'))
  OR 
  (TIPO_REPORT IN ( 'ANNUALE','SEMESTRALE') AND TO_CHAR(DATA_INIZIO,'YYYY') = TO_CHAR(DATA_FINE,'YYYY'))
  )
  ENABLE VALIDATE);
