COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_SOGGETTO IS 'Identificativo del soggetto';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_CAMBIO_RESIDENZA_DOMICILIO IS 'Campo che identifica univocamente un cambio di residenza o domicillio.';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.CONTEGGIO IS 'Flag che indica se il cambio di residenza ha valenza ai fini del conteggio.valorizzato con S se vale per il conteggio, N altrimenti';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.TIPO_ISTANZA IS 'Flag che descrive la tipologia di istanza del cambio di domicilio:- P istanza di parte;- U istanza d''ufficio.';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.DATA_IMMIGRAZIONE IS 'Data in cui è stato effettuato il cambio di residenza o domicilio';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_RESIDENZA IS 'Codice identificativo della residenza associata al cambio di residenza o domicilio. Identifica la residenza di immigrazione';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_FAMIGLIA_CONVIVENZA IS 'Codice identificativo della famiglia o convivenza in cui intende entrare il soggetto immigrante relativo al cambio di residenza o domicilio';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.TIPOLOGIA_CAMBIO IS 'Flag che indica se la pratica è un cambio di residenza o un cambio di abitazione. R se cambio di residenza, A se cambio di abitazione';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_STATO_ESTERO IS 'Identificativo stato CONF_STATO_ESTERO';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_LOCALITA IS 'Identificativo della Località estera di provenienza Da inserire in alternativa al comune di provenienza';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_COMUNE_PROVENIENZA IS 'Identificativo del comune di provenienza del soggetto immigrante del relativo cambio di residenza o domicilio';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_SOGGETTO_RESIDENTE IS 'Identificativo del soggetto residente alla residenza in cui il dichiarante vuole immigrare';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_STATO_PRATICA IS 'Identificativo dello stato di avanzamento della pratica collegata al cambio di residenza o domicilio. CONF_STATO_PRATICA';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_RESIDENZA_PROVENIENZA IS 'Indirizzo di provenienza del dichiarante della pratica';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_TIPO_RICHIESTA_CAMBIO IS 'Codice identificativo della tipologia di richiesta con il quale è pervenuto il relativo cambio di residenza o domicilio';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.CODICE_INDIVIDUALE IS 'Codice utilizzato in APR per identificare univocamente il soggetto';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.DATA_DEFINIZIONE_PRATICA IS 'Data di comunicazione pratica	dd/mm/yyyy';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.SESSO IS 'Sesso del soggetto';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.DATA_PRATICA IS 'Data definizione della pratica';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_FLUSSO IS 'Identificativo del Flusso di RETTIFICA';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_CAUSALE IS 'Identificativo della causale di RETTIFICA';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.FLG_STATO_ELEBORAZIONE IS 'Flg inserimento su OUT_';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.FLG_STATO_RETTIFICA IS 'Flg inserimento su RETTIFICA';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.RETTIFICA_VAL_OLD IS 'In caso di rettifica contiene il vecchio valore del campo COMUNE o STATO';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.RETTIFICA_VAL_NEW IS 'In caso di rettifica contiene il nuovo valore del campo COMUNE o NAZIONE';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.DATA_AGGIORNAMENTO IS 'Data ultimo aggiornamento record';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.DATA_INSERIMENTO IS 'Data inserimento record';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID IS 'Identificativo univico OUT_DECESSI';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.UTENTE_SIPO IS 'Nome operatore';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.FLG_REPORT IS 'Campo tecnico';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.REP_STATO IS 'Campo tecnico';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_MUNICIPIO_IN IS 'Identificativo del municipio della residenza';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_MUNICIPIO_OUT IS 'Identificativo del municipio della residenza';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_CITTADINANZA IS 'Identifica lo stato della prima cittadinanza del soggetto';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.NUMERO_PRATICA IS 'Numero associato alla pratica relativa cambio di residenza o domicilio.';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_TIPO_LEGAME IS 'Identificativo tipo di famiglia/convivenza';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.NUMERO_PERSONE IS 'Numero di persone relative alla pratica di cambio residenza o domicilio';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.CODICE_FISCALE IS 'Codice fiscale del soggetto.';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.DATA_NASCITA IS 'Data di nascita';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_COMUNE_NASCITA IS 'Identificativo del comune di nascita';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_STATO_NASCITA IS 'Identificativo della località di nascita';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_STATO_CIVILE IS 'Codice identificativo dello stato civile attuale del soggetto.';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_POS_PROFESSIONALE_ANPR IS 'Identificativo della posizione professionale del soggetto. (in alternativa con ID_COND_NON_PROFESSIONALE_ANPR)';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_COND_NON_PROFESSIONALE_ANPR IS 'Identificativo della condizione non professionale del soggetto. (in alternativa con ID_POS_PROFESSIONALE_ANPR)';

COMMENT ON COLUMN STAT_USR.OUT_IMMIGRATI.ID_TITOLO_STUDIO_ANPR IS 'Identificativo del titolo di studio del soggetto.';



