COMMENT ON COLUMN STAT_USR.OUT_CITTADINANZE.DATA_NASCITA IS 'data di nascita del soggetto';

COMMENT ON COLUMN STAT_USR.OUT_CITTADINANZE.ID_COMUNE_NASCITA IS 'Identificativo del comune di nascita del soggetto';

COMMENT ON COLUMN STAT_USR.OUT_CITTADINANZE.ID_STATO_NASCITA IS 'Identificativo dello stato di nascita del soggetto';

COMMENT ON COLUMN STAT_USR.OUT_CITTADINANZE.ID_STATO_CIVILE IS 'Identificativo dello stato civile del soggetto';

